    if (tickReworkLatch) return tickReworkLatch;
    var state = { map: {} };
    var cfg = reworkLatchStateCfg();
    var repoInfo = null;
    if (cfg) {
        if (cfg.repo) {
            var parts = String(cfg.repo).split('/');
            repoInfo = { owner: parts[0], repo: parts[1] };
        } else {
            repoInfo = effectiveRepoInfo || null;
        }
