        } catch (eLatchPrev) {
            // Any miss (first tick, 404, rate limit) → empty map: the armer
            // keeps today's behavior and the snapshot re-seeds the latch.
        }
    }
    tickReworkLatch = state;
    return tickReworkLatch;
}

