    var fileReadMock = function(readOpts) {
        var p = readOpts.path;
        var isConfigDiscovery = p.indexOf('.dmtools/config') !== -1;

        if (opts.fileMap && opts.fileMap.hasOwnProperty(p)) {
            return opts.fileMap[p];
