        var p = { jobParams: { owner: 'epam', repo: 'dmtools-dart',
            machineAuthor: 'ai-teammate', rules: rules } };
        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) p.jobParams[k] = extra[k]; } }
        return p;
    }

